import java.util.*;

class Solution {
  public int minLengthAfterRemovals(List<Integer> nums) {
    int n = nums.size(), i = 0, j = (n + 1) / 2, pairs = 0;
    while (i < n / 2 && j < n) {
      if (nums.get(i) < nums.get(j)) {
        pairs++;
        i++;
        j++;
      } else j++;
    }
    return n - 2 * pairs;
  }
}
